const regexMetacharacters = new Set(['\\', '.', '^', '$', '*', '+', '?', '(', ')', '[', ']', '{', '}', '|'])

const normalizedDictionaries = Object.fromEntries(
  (['hi', 'bn'] as const).map((language) => {
    const dictionary = Object.fromEntries(
      Object.entries(dictionaries[language]).map(([source, target]) => [source.replace(/[’‘]/g, "'"), target]),
    )
    return [language, { dictionary, entries: Object.entries(dictionary).sort(([a], [b]) => b.length - a.length) }]
  }),
) as Record<Exclude<Language, 'en'>, { dictionary: Record<string, string>; entries: [string, string][] }>

export function LocaleProvider({ language, children }: { language: Language; children: React.ReactNode }) {
  return <localeContext.Provider value={language}>{children}</localeContext.Provider>
}

export function useLocale() {
  return useContext(localeContext)
}

export function translateText(text: string, language: Language) {
  if (language === 'en') return text
  const { dictionary, entries } = normalizedDictionaries[language]
  const leading = text.slice(0, text.length - text.trimStart().length)
  const trailing = text.slice(text.trimEnd().length)
  const phrase = text.trim().replace(/[’‘]/g, "'")
  let translated = dictionary[phrase]
  if (!translated) {
    translated = entries.reduce((result, [source, target]) => {
      const escapedSource = [...source].map((character) => regexMetacharacters.has(character) ? `\\${character}` : character).join('')
      const wholePhrase = new RegExp(`(?<![A-Za-z0-9])${escapedSource}(?![A-Za-z0-9])`, 'g')
      return result.replace(wholePhrase, target)
    }, phrase)
  }

  return `${leading}${translated}${trailing}`
}

function translateNode(node: React.ReactNode, language: Language): React.ReactNode {
  if (typeof node === 'string') return translateText(node, language)
  if (Array.isArray(node)) {
    // Preserve the original key on each child so React can reconcile correctly.
    // Without this, array children lose their keys after cloneElement, flooding
    // the React reconciler with key-prop warnings and causing a blank render in
    // React 19 strict mode.
    return node.map((child, index) => {
      const translated = translateNode(child, language)
      if (React.isValidElement(translated)) {
        const existingKey = translated.key ?? String(index)
        return React.cloneElement(translated as React.ReactElement, { key: existingKey })
      }
      return translated
    })
  }
  if (!React.isValidElement(node)) return node

  const props = node.props as Record<string, unknown> & { children?: React.ReactNode }
  if (props['data-no-translate'] === 'true') return node
  const translatedProps: Record<string, unknown> = {}
  for (const attribute of ['aria-label', 'aria-description', 'title', 'placeholder', 'alt']) {
    const value = props[attribute]
    if (typeof value === 'string') translatedProps[attribute] = translateText(value, language)
  }
  if (props.children !== undefined) translatedProps.children = translateNode(props.children, language)
  return React.cloneElement(node, translatedProps)
}

export function TranslateTree({ children }: { children: React.ReactNode }) {
  const language = useLocale()
  return <>{translateNode(children, language)}</>
}
